:root {
  --bg-board: #2c1a0e;
  --bg-section: #3d2512;
  --bg-header: #1a0e06;
  --accent-gold: #d4a017;
  --accent-red: #b83232;
  --accent-green: #3a7d44;
  --accent-teal: #2a7d6e;
  --text-light: #f5e6c8;
  --text-muted: #a8896a;
  --text-white: #fff8ee;
  --tag-new-bg: #3a7d44;
  --tag-dark-bg: #2a4a6e;
  --divider: #5c3a1e;
  --footer-bg: #1a0e06;
  --badge-featured-bg: #d4a017;
  --badge-featured-text: #1a0e06;
}

article.menu-board {
  background-color: var(--bg-board);
  border: 3px solid var(--accent-gold);
  border-radius: 12px;
  width: 480px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.board-header {
  background-color: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  border-bottom: 2px solid var(--accent-gold);
}

.board-icon {
  font-size: 22px;
  line-height: 1;
}

.board-title-group {
  text-align: center;
}

.board-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--accent-gold);
  margin: 0;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1.1;
}

.board-tagline {
  font-size: 11px;
  color: var(--text-muted);
  margin: 2px 0 0;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.board-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  padding: 14px 16px;
  flex: 1;
}

.menu-section {
  flex: 1;
}

.divider-col {
  width: 1px;
  background-color: var(--divider);
  margin: 0 14px;
  border-radius: 1px;
}

.section-heading {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent-red);
  margin: 0 0 10px;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--divider);
}

.menu-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.menu-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.item-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-light);
  display: flex;
  align-items: center;
  gap: 5px;
  line-height: 1.3;
}

.item-tag {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 1px 5px;
  border-radius: 3px;
  background-color: var(--tag-new-bg);
  color: var(--text-white);
}

.item-tag.hot {
  background-color: transparent;
  padding: 0;
  font-size: 11px;
}

.item-tag[class="item-tag"] {
  background-color: var(--tag-dark-bg);
}

.item-price {
  font-size: 14px;
  font-weight: 700;
  color: var(--accent-gold);
  white-space: nowrap;
}

.board-footer {
  background-color: var(--footer-bg);
  border-top: 2px solid var(--accent-gold);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  gap: 10px;
}

.footer-badge {
  display: flex;
  flex-direction: column;
  align-items: center;
  background-color: var(--bg-section);
  border: 1px solid var(--divider);
  border-radius: 6px;
  padding: 4px 10px;
  min-width: 80px;
}

.footer-badge.featured {
  background-color: var(--badge-featured-bg);
  border-color: var(--accent-gold);
}

.footer-badge.featured .badge-label {
  color: var(--badge-featured-text);
  opacity: 0.7;
}

.footer-badge.featured .badge-value {
  color: var(--badge-featured-text);
}

.badge-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  line-height: 1.2;
}

.badge-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-light);
  line-height: 1.3;
}

.footer-note {
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  flex: 1;
  line-height: 1.4;
}
